window.getStudentGradeData = function(noOrId) {
    if (!window.TERM1_GRADES_DATA) return null;
    var target = window.TERM1_GRADES_DATA.find(function(s) {
        return parseInt(s.no, 10) === parseInt(noOrId, 10) || String(s.student_id) === String(noOrId);
    });
    return target || null;
};
